// PROTOTYPE: independently written interaction sketches from the design specs.
import { facts, steps, demoProposals } from './demo-state.js';
export const escapeHTML = (text) => String(text).replace(/[&<>"']/g, (char) => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' }[char]));
const e = escapeHTML;
const button = (label, action, extra = '') => `<button type="button" data-action="${action}" ${extra}>${label}</button>`;
const go = (page, label) => `<button type="button" class="page-link" data-page="${page}">${label} <span aria-hidden="true">↗</span></button>`;
const note = (text) => `<p class="dashboard-note">${text}</p>`;
const heading = (title, text = '') => `<h3>${title}</h3>${text ? `<p>${text}</p>` : ''}`;
const complete = (state, index) => [state.boxOpened, state.bookRead, state.measured, facts(state).fit && state.checked, state.approved][index];
export function journey(state, active) {
  return `<nav class="journey-strip" aria-label="Demo journey">${steps.map((step, index) => `<button type="button" data-page="${step.page}" ${active === step.page ? 'aria-current="step"' : ''}><span>${complete(state,index) ? '✓' : String(index + 1).padStart(2,'0')} · ${step.kind}</span>${step.title}</button>`).join('')}</nav>`;
}
function artifact(kind, caption) {
  const shape = kind === 'box' ? '<path d="M25 58 112 17 203 57 116 103Z" fill="#ede4cd"/><path d="M25 58v79l91 48v-82Z" fill="#d8cab0"/><path d="M116 103v82l87-44V57Z" fill="#b9a889"/><path d="m62 39 91 44v38l34-17V68l-90-43Z" fill="#B84F2B"/><text x="43" y="114" transform="rotate(28 43 114)" font-size="12" fill="#22303c">A TRAIN AROUND THE TREE</text>' : kind === 'book' ? '<path d="M26 32h88q18-12 88 0v132q-66-12-88 0H26Z" fill="#e8ddc5" stroke="#22303c" stroke-width="2"/><path d="M114 32v132" stroke="#22303c"/><path d="M40 58h59M40 73h48M40 88h55M130 60h53M130 76h42" stroke="#8b8170"/><rect x="136" y="99" width="34" height="32" fill="#b84f2b"/><circle cx="147" cy="107" r="3" fill="#fdfbf5"/><circle cx="161" cy="107" r="3" fill="#fdfbf5"/><text x="39" y="142" font-size="12" fill="#22303c">01 / 03</text>' : '<path d="M60 24h110l-7 17 12 22-6 111H60L50 62l15-21Z" fill="#e7e8df" stroke="#22303c" stroke-width="2"/><path d="M62 41h104M65 29h97" stroke="#8b8170"/><rect x="83" y="68" width="57" height="50" fill="#b84f2b"/><text x="111" y="102" text-anchor="middle" font-size="30" fill="#fdfbf5">1</text><path d="M73 134h25v19H73ZM114 128h35v24h-35Z" fill="#718d74"/>';
  return `<figure class="artifact-illustration"><svg viewBox="0 0 230 200" role="img" aria-label="${e(caption)}">${shape}</svg><figcaption>${caption}</figcaption></figure>`;
}
export function proposalSketch(shape, label) {
  return `<svg viewBox="0 0 250 140" class="proposal-sketch" role="img" aria-label="${e(label)}"><path d="M15 122h220" stroke="currentColor" stroke-width="2"/>${shape === 'lantern' ? '<rect x="94" y="69" width="62" height="49" fill="#e4ddc6" stroke="#22303c"/><rect x="120" y="21" width="9" height="80" fill="#b84f2b"/><path d="M102 24h45l-9-16h-26Z" fill="#22303c"/><rect x="109" y="25" width="30" height="24" fill="#e5b448"/><path d="M85 116h83" stroke="#22303c" stroke-width="4"/>' : '<path d="M32 85h187v18H32Z" fill="#c5d5dc" stroke="#22303c"/><path d="M55 102h18v19H55ZM180 102h18v19h-18Z" fill="#b84f2b"/><path d="M43 58h165v12H43ZM48 65v22M87 65v22M126 65v22M165 65v22M203 65v22" stroke="#22303c" stroke-width="5"/>'}</svg>`;
}
function plan(state) {
  const offset = state.offset * 3;
  const f = facts(state);
  return `<svg class="plan-drawing" viewBox="0 0 400 290" role="img" aria-label="Demo plan. Tree base ${state.measurement} studs wide. Ring offset ${state.offset} studs. ${f.fit ? 'Demo fit check passes' : 'Base overlaps the inner corner'}."><defs><pattern id="stud-grid" width="12" height="12" patternUnits="userSpaceOnUse"><circle cx="6" cy="6" r="1" fill="currentColor" opacity=".18"/></pattern><pattern id="overlap-hatch" width="6" height="6" patternUnits="userSpaceOnUse" patternTransform="rotate(45)"><line x1="0" x2="0" y2="6" stroke="#b84f2b" stroke-width="2"/></pattern></defs><rect width="400" height="290" fill="url(#stud-grid)"/><rect x="22" y="18" width="356" height="254" fill="none" stroke="currentColor"/><g transform="translate(${offset} 0)"><circle cx="190" cy="143" r="102" fill="none" stroke="currentColor" stroke-width="13" opacity=".45"/><circle cx="190" cy="143" r="102" fill="none" stroke="var(--dt-sheet)" stroke-width="3" stroke-dasharray="3 6"/><path d="M190 143h106v105H190Z" fill="var(--dt-info-bg)" stroke="var(--dt-info)" stroke-dasharray="4 3"/><text x="220" y="240" fill="currentColor" font-size="11">Section NE</text></g><rect x="${190-state.measurement*1.5}" y="${143-state.measurement*1.5}" width="${state.measurement*3}" height="${state.measurement*3}" fill="var(--dt-pass-bg)" stroke="var(--dt-pass)" stroke-width="2"/><text x="190" y="138" text-anchor="middle" fill="currentColor" font-size="11">TREE</text><text x="190" y="153" text-anchor="middle" fill="currentColor" font-size="11">${state.measurement} × ${state.measurement}</text>${!f.fit ? '<rect x="191" y="144" width="24" height="24" fill="url(#overlap-hatch)"/>' : ''}<text x="28" y="35" fill="currentColor" font-size="10">MOCK GEOMETRY · not a fit certificate</text></svg>`;
}
const ledger = (state, count = 4) => `<ol class="ledger">${state.log.slice(-count).reverse().map((item) => `<li><span>${e(item.origin)}</span>${e(item.text)}</li>`).join('')}</ol>`;
const status = (text, pass = false) => `<p class="check-result ${pass ? 'pass' : ''}" role="status">${pass ? '✓' : '○'} ${text}</p>`;

export function renderSheet(module, state) {
  const f = facts(state);
  let main = '', rail = '';
  const reset = button('Reset demo work', 'reset', 'class="quiet"');
  switch (module.code) {
    case 'HUB':
      main = heading('The picture on the box', 'A train runs around the Christmas tree. We can show the measurements, explain the fit, and trace the parts before anyone spends money.') + `<div class="hero-artifact">${artifact('box', 'A demo box of work')}${go('BOX','Open the box of work')}</div>`;
      rail = heading('Right now') + steps.slice(2).map((step, i) => `<div class="priority"><span class="micro">${complete(state,i+2) ? 'DONE IN DEMO' : `NUMBERED BAG ${i+1}`}</span><h4>${step.title}</h4><p>${step.hint}</p>${go(step.page,'Go to the sheet')}</div>`).join('') + reset;
      break;
    case 'BOX':
      main = artifact('box', 'Demo work box · A train around the tree') + heading('What opening this box means', 'Start one bounded piece of work. Its book states the result; its bags keep the next step small.') + `<dl class="facts-list"><div><dt>On the box</dt><dd>A train circle that fits, with a parts list whose basis can be explained.</dd></div><div><dt>Inside</dt><dd>One instruction book · three numbered bags · a place to step back.</dd></div><div><dt>Operator</dt><dd>James decides what becomes real work.</dd></div></dl>` + (state.boxOpened ? status('Box opened in this tab.',true) + go('V-01','Read the instruction book') : button('Open this demo box','open-box','class="primary"'));
      rail = heading('A box of work / a physical box') + `<p>This journey uses the existing delivery metaphor. A work box is an agreed outcome; a physical inventory box is something James owns. They share a shape, but each record says which it is.</p>${go('I-02','Document a physical box')}${go('I-01','Look at physical inventory')}` + note('MOCK WORK · nothing in the inventory has been changed.');
      break;
    case 'I-02':
      main = artifact('box', 'A physical inventory box · fictional sample') + heading('What is actually in this box', 'Document the contents before treating them as available. A photo or a count supports a physical record.') + `<dl class="facts-list"><div><dt>Box label</dt><dd>Sample box A · on the shelf</dd></div><div><dt>Contents</dt><dd>32 support plates · mock counted contents</dd></div><div><dt>Evidence</dt><dd>Sample count only. No photograph is attached.</dd></div></dl>` + (state.physicalBoxDocumented ? status('Sample physical box documented in this tab.',true) : button('Document this sample box','document-box','class="primary"'));
      rail = heading('A physical box / a box of work') + `<p>This page concerns inventory containers. The delivery metaphor has its own view, where a box is an agreed outcome and bags are bounded pieces of work.</p>${go('I-01','See physical inventory')}${go('BOX','Open a box of work')}${go('R-01','Review a sample parcel')}`;
      break;
    case 'V-01':
      main = artifact('book', 'A small instruction book for this box') + heading('One numbered bag at a time') + `<ol class="book-steps">${steps.slice(2).map((step,i) => `<li><span class="bag-number">${i+1}</span><div><h4>${step.title}</h4><p>${step.hint}</p>${go(step.page,'Open this sheet')}</div></li>`).join('')}</ol>` + button(state.bookRead ? 'Book read · start Bag 1' : 'I have read the book · start Bag 1','read-book','class="primary"');
      rail = heading('Before you build') + `<p>Use the sample value, or try another value from 8 to 28 studs. Each change keeps the earlier reading and reopens the checks that depend on it.</p><p>This book is an interaction script, not an accepted work order or official LEGO instructions.</p>${go('V-02','Replay the three steps')}`;
      break;
    case 'M-01':
      main = heading('Bag 1 · what the tape says', 'The base width is a fictional reading for this demo. Record it, then see what needs checking again.') + `<div class="measurement-card"><span class="micro">TREE BASE WIDTH · MOCK MATH</span><p class="big-number">${state.measurement}<span>studs</span></p><p>${state.measured ? 'Recorded by James in this demo tab.' : 'Sample reading · not yet recorded in this demo.'}</p><label for="measurement-input">New reading, in studs</label><div class="input-action"><input id="measurement-input" name="measurement" type="number" min="8" max="28" step="1" value="${state.measurementDraft}" /><button type="button" data-action="propose-measurement">Review this reading</button></div></div>`;
      if (state.pendingMeasurement !== null) main += `<div class="restatement" role="status"><h3>Before it becomes the record</h3><p>I will record the tree base as <strong>${state.pendingMeasurement} studs</strong>, replacing the sample ${state.measurement}-stud reading. The earlier value stays on record. Layout and parts checks will need another look; any demo approval will reopen.</p>${button('Yes, record it','confirm-measurement','class="primary"')}${button('Not yet','cancel-measurement')}</div>`;
      main += `<details><summary>Earlier readings · retained</summary>${state.revisions.length ? `<ol>${state.revisions.map((value) => `<li>${value} studs · earlier demo revision</li>`).join('')}</ol>` : '<p>No earlier demo revisions yet.</p>'}</details>`;
      rail = heading('What leans on this number') + `${go('A-01','Does the base clear the layout?')}${go('C-01','Does the parts list still hold?')}${go('W-00','See the change trail')}` + note('Method: demo numeric entry. Verification: unverified mock. Authority: none. Origin: human-entered sample.') + (state.measured ? go('A-01','Continue to Bag 2') : '<p>Record a reading to continue the guided journey.</p>');
      break;
    case 'A-01':
      main = heading('Bag 2 · make room around the tree', 'Try moving the ring centre. This deliberately simplified test shows how a measured fact becomes a check.') + plan(state) + `<label for="offset-input">Ring-centre offset · studs</label><input id="offset-input" type="range" min="0" max="16" step="1" value="${state.offset}" /><output for="offset-input" id="offset-value">${state.offset} studs</output><div class="button-row">${button('Try a clear position','clear-fit')}${button('Check this layout','check-layout','class="primary"')}</div>`;
      rail = heading('Does it fit?') + status(!state.measured ? 'Record the base first.' : f.fit ? 'Demo base clearance passes.' : 'Base overlaps the section corner.',f.fit) + status(state.checked ? 'Layout checked against the current reading.' : 'Layout check still needs a look.',state.checked) + `<p>Rule in this demo: offset ≥ half the base width. It illustrates dependency flow and does not implement the design package’s real geometry.</p>${go('M-01','Look at the measurement')}${go('C-01','Continue to Bag 3')}`;
      break;
    case 'C-01':
      main = heading('Bag 3 · step back and look', 'Parts counts follow the same demo state as the layout. Each row retains its basis.') + `<div class="table-scroll"><table><caption>Demo parts · MOCK MATH</caption><thead><tr><th>Part / basis</th><th>Need</th><th>Own</th><th>Gap</th></tr></thead><tbody><tr><th>Track support plates <span>Own design · sample formula</span></th><td>${f.need}</td><td>${f.owned}</td><td>${f.need-f.owned}</td></tr><tr><th>Train track <span>Official set · sample count</span></th><td>16</td><td>16</td><td>0</td></tr><tr><th>Ballast detail <span>AI research suggestion · unverified</span></th><td>12</td><td>0</td><td>12</td></tr></tbody></table></div>` + note('The AI suggestion stays visible as AI-originated research. It is not included in a released list.') + `<div class="gate"><h3>Review this demo list</h3><p>${!state.measured ? 'First record Bag 1’s measurement.' : !f.fit || !state.checked ? 'Bag 2 must clear the base and be checked against the current reading.' : state.approved ? 'Demo approval recorded. Any measurement or layout change reopens it.' : 'The demo checks are ready. Initial this review to finish the journey.'}</p><label for="initials-input">Your initials · demo only</label><input id="initials-input" maxlength="5" placeholder="JW" /><div class="button-row">${button(state.approved ? 'Reviewed in demo' : 'Record demo review','approve',`${!state.measured || !f.fit || !state.checked || state.approved ? 'disabled' : ''} class="primary"`)}</div><p class="micro">This never releases a BOM or authorizes a purchase.</p></div>`;
      rail = heading('Evidence before the stamp') + status(`${state.measurement} studs · ${state.measured ? 'recorded sample' : 'sample, unrecorded'}`,state.measured) + status(`Fit ${f.fit ? 'passes in mock geometry' : 'needs attention'}`,f.fit) + status(`Review ${state.approved ? 'complete in demo' : 'open'}`,state.approved) + `${go('M-01','Change a reading')}${go('P-01','Preview buying the gap')}${go('H-01','Read the demo handoff')}`;
      break;
    case 'P-01':
      main = heading('What remains to find', 'Buying stays outside this prototype. This sheet shows the boundary after a parts review.') + `<p class="big-number">${f.need-f.owned}<span>support plates · mock gap</span></p>${status(state.approved ? 'Demo review complete. No real release exists.' : 'Demo review still open.',state.approved)}<table><caption>Fictional shop comparison · not live prices</caption><thead><tr><th>Option</th><th>Sample range</th><th>Trade-off</th></tr></thead><tbody><tr><th>One parcel</th><td>£8–12</td><td>Fewer shipments</td></tr><tr><th>Two parcels</th><td>£6–14</td><td>Shipping still unknown</td></tr></tbody></table>` + note('No cart, order, or spend action is enabled. A real list needs its release gate and current price evidence.');
      rail = heading('Before anything is bought') + `${go('C-01','Return to the list')}${go('R-01','Try receiving a sample parcel')}`;
      break;
    case 'I-01':
      main = heading('Owned, built, and free to use', 'A sample inventory illustrates the difference between ownership and availability.') + `<table><caption>Physical inventory · fictional</caption><thead><tr><th>Item</th><th>Owned</th><th>Reserved</th><th>Free</th></tr></thead><tbody><tr><th>Support plates</th><td>${32+(state.received ? 8 : 0)}</td><td>16</td><td>${16+(state.received ? 8 : 0)}</td></tr><tr><th>Train track</th><td>16</td><td>16</td><td>0</td></tr></tbody></table>${go('I-03','Look closely at one set')}`;
      rail = heading('Inventory stays separate') + `<p>Changing the tree measurement reopens the layout and parts review. It does not change what is physically owned.</p>${go('M-01','Try changing the measurement')}${go('R-01','Review the sample parcel')}`;
      break;
    case 'I-03':
      main = heading('One set · Christmas tree') + `<dl class="facts-list"><div><dt>Design reference</dt><dd>Set 41843 · DEC-016 is cited by the design bundle.</dd></div><div><dt>Demo width</dt><dd>${state.measurement} studs · fictional state in this tab.</dd></div><div><dt>Physical record</dt><dd>The real record and photos are not edited by this prototype.</dd></div></dl>${go('M-01','Measure and check')}`;
      rail = heading('Keep the source visible') + note('The design reference identifies a source; it does not verify this demo’s invented reading.') + go('I-01','Back to what we have');
      break;
    case 'T-01':
      main = heading('Waiting work and its reason') + `<ol class="work-queue">${steps.slice(2).map((step,i) => `<li><span class="bag-number">${i+1}</span><div><h4>${step.title}</h4><p>${complete(state,i+2) ? 'Done in this demo tab.' : step.hint}</p>${go(step.page,'Open the work')}</div></li>`).join('')}</ol>`;
      rail = heading('Latest activity') + ledger(state);
      break;
    case 'R-01':
      main = artifact('bag','A physical parcel · sample inventory') + heading('A parcel does not count until it is checked', 'This sample contains eight support plates. Recording receipt only changes the demo inventory; it does not erase an order or infer authority.') + (state.received ? status('Eight sample plates received in this tab.',true) : button('Counted eight · record demo receipt','receive','class="primary"')) + go('I-01','See what we have');
      rail = heading('Receipt provenance') + note('Origin: human-entered sample. Method: counted in the demo. Verification: mock only. No real parcel or order is represented.');
      break;
    case 'V-02':
      main = artifact('bag',`Replay · step ${state.replayStep+1} of 3`) + heading(['Open the numbered bag','Build the small piece','Step back and check'][state.replayStep], ['Keep the remaining work packed away.','Follow this bag’s book. Ask when the instruction is unclear.','Compare the result with the picture on the box. Retain what changed.'][state.replayStep]) + `<div class="button-row">${button('Previous step','replay-prev',state.replayStep===0?'disabled':'')}${button('Next step','replay-next',state.replayStep===2?'disabled':'')}</div>${go(steps[state.replayStep+2].page,'Try this step on its sheet')}`;
      rail = heading('Build order / system layers') + `<p>A numbered bag expresses an order of work. Exploding the house reveals system modules. Those two orders can differ.</p>${go('J-01','See the route between sheets')}`;
      break;
    case 'B-01':
      main = heading('AI question · awaiting a human answer') + `<div class="question-block"><span class="origin-label">AI · scripted demo</span><p>“The tree base overlaps a section corner. Would you rather try moving the ring centre, or explore a notch in the section?”</p></div><label for="answer-input">Your answer, in your own words</label><textarea id="answer-input" rows="3" placeholder="Try moving the ring first…">${e(state.answer)}</textarea>${button('Keep this answer in the demo','answer','class="primary"')}${go('A-01','Try the move')}`;
      rail = heading('What the AI may do here') + `<p>Ask about a visible model or a constraint. Restate a suggested change. It cannot decide a builder’s meaning, approve a list, or quietly modify the sheet.</p>` + note('No AI service is connected. This is a scripted question with permanently visible AI origin.');
      break;
    case 'F-01':
    case 'F5':
      main = heading('Your model, your story', 'Build first. Then tell us what it means to you. A human host can invite questions about the model.') + proposalSketch('lantern','Sample lantern model; its builder supplies the meaning') + `<label for="story-input">What would you like to tell us about your model?</label><textarea id="story-input" rows="3" placeholder="This part of my model means…">${e(state.storyDraft)}</textarea><label class="checkbox-label"><input id="story-consent" type="checkbox" ${state.storyConsent?'checked':''} /> Show my story in this local demo session</label>${button('Keep my words in this session','story','class="primary"')}` + (state.story && state.storyConsent ? `<div class="builder-story"><span class="micro">YOUR WORDS · retained verbatim in this tab</span><blockquote>${e(state.story)}</blockquote></div>` : '');
      rail = heading('Brick facts · a separate channel') + `<p>Sample footprint: 8 × 8 studs. Height: 6 bricks. Both are mock facts; neither tells us what your model means.</p><p class="origin-label">AI · suggested question</p><p>“Could you show us the part you want us to notice?”</p>${go('F6','Compare the separate ideas')}` + note('Research adaptation inspired by LEGO SERIOUS PLAY. This is not an official workshop. Nothing is published or saved after reload.');
      break;
    case 'F6':
      main = heading('See each idea before a shared version', 'Each builder’s words stay attached to their model. Questions ask about the model; feasibility remains separate.') + `<div class="proposal-pair">${demoProposals.map((idea) => `<article><span class="micro">${idea.builder}</span><h4>${idea.name}</h4>${proposalSketch(idea.shape,idea.name)}<blockquote>${idea.story}</blockquote>${button(state.heard.includes(idea.id) ? 'Story heard in demo' : 'Hear this story',`hear-${idea.id}`,state.heard.includes(idea.id)?'disabled':'')}</article>`).join('')}</div>` + (state.shared ? note('Shared concept preview: lantern + bridge. Both original models and their stories remain above. This preview makes no decision for either builder.') : button('Preview a shared landscape','shared',`${state.heard.length<2?'disabled':''} class="primary"`));
      rail = heading('Before bringing ideas together') + status(`${state.heard.length} of 2 sample stories heard.`,state.heard.length===2) + `<p>Everyone has a model and a story before discussion of a shared version. Hearing a story is not consent to merge or publish it.</p>${go('F5','Add your own story')}${go('F7','Explore a what-if')}`;
      break;
    case 'F7':
      main = heading('What if a measurement changes after review?', 'Try a situation from the research issues: a number changes after someone has approved the plan.') + note('Challenge: the base is two studs wider than the current reading. What should reopen? What should stay on record?') + `${button('Try the wider base in the demo','what-if','class="primary"')}${state.whatIf ? status('Layout and parts review reopened. Earlier reading retained. Inventory stayed the same.',true) : ''}${go('W-00','See the trail')}`;
      rail = heading('Ask about the system') + `<p>“Show us which piece of your model is affected.”</p><p>A human host can compare possible responses before choosing a change. The challenge is grounded in issue #40’s failure scenarios.</p>${go('M-01','Review the new reading')}`;
      break;
    case 'F8':
      main = heading('A stack you can point to') + `<div class="stack-diagram"><div><span>BOX · AGREED RESULT</span><strong>A train that fits</strong></div><div><span>BOOK · CONTEXT AND BOUNDARIES</span><strong>What the builder wants / what is known</strong></div><div><span>BAG · BOUNDED AGENT WORK</span><strong>Propose → check → human review</strong></div><div><span>ON THE TABLE · ARTIFACT</span><strong>Model + story + evidence</strong></div></div>${go('B-01','See a scripted AI question')}`;
      rail = heading('Minifigs in the house') + `<p>Three model figures mark a sample run, a review, and a story. They are labelled demo activity, not live agents.</p><p>A future figure could open the artifact and its state. Ownership, verification, and authority need separate fields.</p>` + note('The house is a navigation model, not a settled agent architecture.');
      break;
    case 'J-01':
      main = heading('Follow one journey through the sheets') + `<ol class="book-steps">${steps.map((step,index) => `<li><span class="bag-number">${index+1}</span><div><h4>${step.title}</h4><p>${step.hint}</p>${go(step.page,step.page)}</div></li>`).join('')}</ol>`;
      rail = heading('A useful first route') + `<p>This prototype follows one journey from the wider design’s thirteen. It tests entry and return, the box/bag/book vocabulary, and dependencies between sheets.</p>${reset}`;
      break;
    case 'H-01':
      main = heading('What this demo can hand over') + `<dl class="facts-list"><div><dt>Measurement</dt><dd>${state.measurement} studs · ${state.measured ? 'recorded mock' : 'unrecorded sample'}</dd></div><div><dt>Layout</dt><dd>${state.checked && f.fit ? 'Checked in simplified mock geometry' : 'Check remains open'}</dd></div><div><dt>Parts review</dt><dd>${state.approved ? 'Initialled in this demo only' : 'Open'}</dd></div><div><dt>Real authority</dt><dd>None. James must review a real implementation and its evidence.</dd></div></dl>` + (state.approved ? `<div class="completion"><span>✓</span><h3>You finished the three demo bags.</h3><p>Try a wider base next. The record should retain the old reading and reopen the review.</p>${go('F7','Try the what-if')}</div>` : go('C-01','Finish the review'));
      rail = heading('Known limits') + `<p>PR #44 is a research overlay. W-00 is a wireframe, with a known whole-page flashing implementation. This demo uses a separate canvas and element transitions; production state, storage, routing, evidence schemas, and performance design remain work.</p>` + reset;
      break;
    case 'W-00':
      main = heading('What changed because of this', 'One measurement changes its dependent checks. This trail records the cause; unrelated inventory stays intact.') + ledger(state,10) + `${go('M-01','Change the base width')}${go('A-01','See the reopened fit check')}`;
      rail = heading('Frame study · explicit limits') + `<p>The source’s document-level transitions flashed whole pages. Here only the house camera, selected block, and sheet threshold move. There is no global view-transition snapshot.</p><p>The trail is tab-local mock state. It is not the correspondence ledger, durable event storage, or an authority record.</p>`;
      break;
    default: main = heading(module.title,module.detail); rail = go('HUB','Return to the drafting table');
  }
  return `${journey(state,module.code)}<main class="dashboard-main">${main}</main><aside class="dashboard-rail" aria-label="Context and next steps">${rail}</aside>`;
}
